CREATE TABLE public.ledger_entry (
    id bigint NOT NULL,
    run_id bigint NOT NULL,
    source text NOT NULL,
    source_file text NOT NULL,
    source_line integer NOT NULL,
    raw_payload jsonb NOT NULL,
    settlement_id text DEFAULT ''::text NOT NULL,
    txn_ref text DEFAULT ''::text NOT NULL,
    merchant_order_id text DEFAULT ''::text NOT NULL,
    adjustment_id text DEFAULT ''::text NOT NULL,
    shipment_id text DEFAULT ''::text NOT NULL,
    sku text DEFAULT ''::text NOT NULL,
    quantity integer,
    transaction_type text DEFAULT ''::text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    amount_type text DEFAULT ''::text NOT NULL,
    amount_description text DEFAULT ''::text NOT NULL,
    amount_field text DEFAULT ''::text NOT NULL,
    transaction_type_raw text DEFAULT ''::text NOT NULL,
    description_raw text DEFAULT ''::text NOT NULL,
    marketplace text DEFAULT ''::text NOT NULL,
    fulfilment text DEFAULT ''::text NOT NULL,
    order_city text DEFAULT ''::text NOT NULL,
    order_state text DEFAULT ''::text NOT NULL,
    order_postal text DEFAULT ''::text NOT NULL,
    transaction_status text DEFAULT ''::text NOT NULL,
    amount numeric(18,4) NOT NULL,
    posted_at timestamp with time zone,
    released_at timestamp with time zone,
    event_date date,
    record_ref text DEFAULT ''::text NOT NULL,
    summary_field text DEFAULT ''::text NOT NULL,
    config_id integer,
    match_kind text DEFAULT 'UNMAPPED'::text NOT NULL,
    route_seq smallint DEFAULT 0 NOT NULL,
    in_scope boolean DEFAULT false NOT NULL,
    CONSTRAINT ledger_entry_source_check CHECK ((source = ANY (ARRAY['PAYMENT'::text, 'SETTLEMENT'::text])))
);


